function C:SetChosenDayText(lang, _DataNumber)
  self.days.options:Clear()
  do
    local num = 30
    while num >= 2 do
      if SaveRelayer.IsSlotDataExists(("Data" .. TOSTR(_DataNumber) .. "_Day" .. TOSTR(num) .. TOSTR(SaveRelayer.EXTENTION))) then
        self.days.options:Add(INIT(NEW("OptionData", nil), { text = NgoEx.DayText(num, Settings.CurrentLanguage.Value, false) }))
      end
      num = num - 1
    end
  end
  self.days.options:Add(INIT(NEW("OptionData", nil), { text = NgoEx.DayText(1, Settings.CurrentLanguage.Value, false) }))
  self.days:RefreshShownValue()
  if SaveRelayer.IsSlotDataExists(("Data" .. TOSTR(_DataNumber) .. "_Day1" .. TOSTR(SaveRelayer.EXTENTION))) then
    self.DataIcon.sprite = self.ten
    self.NewAccount.gameObject:SetActive(true)
    self.NewAccount:GetComponentInChildren("TMP_Text").text = NgoEx.SystemTextFromType("Start_Menu_Newgame01", Settings.CurrentLanguage.Value)
    self.StartButton:GetComponentInChildren("TMP_Text").text = NgoEx.SystemTextFromType("Start_Menu_Continue", Settings.CurrentLanguage.Value)
  else
    self.DataIcon.sprite = self.ame
    self.NewAccount.gameObject:SetActive(false)
    self.StartButton:GetComponentInChildren("TMP_Text").text = NgoEx.SystemTextFromType("Start_Menu_Newgame00", Settings.CurrentLanguage.Value)
  end
end

function C:setChosenDay()
  self.chosenDay = CONCAT("Day", Regex.Replace(IDX(self.days.options, self.days.value).text, "[^0-9]", ""))
  self.days.onValueChanged:AddListener(function()
    self.chosenDay = CONCAT("Day", Regex.Replace(IDX(self.days.options, self.days.value).text, "[^0-9]", ""))
  end)
end

function C:Resume(datanum, datapath)
  if not coroutine.isyieldable() then spawn(C.Resume, self, datanum, datapath) return end
  CursorManager:SetCursorShowHide(false)
  self:showWelcome(false)
  Settings.saveNumber = datanum
  Settings.isBackToLoad = true
  Settings.nowSaveFile = CONCAT(datapath, SaveRelayer.EXTENTION)
  Resources.UnloadUnusedAssets():ToUniTask(nil, "Update", nil, false)
  SceneManager.LoadSceneAsync("WindowUITestScene")
end

function C:showWelcome(startover)
  if not coroutine.isyieldable() then spawn(C.showWelcome, self, startover) return end
  self.ChooseDay.alpha = 0
  self.ChooseDay.interactable = false
  self.ChooseDay.blocksRaycasts = false
  self.Welcome.alpha = 1
  self.Welcome.interactable = true
  self.Welcome.blocksRaycasts = true
  if ControllerGuideManager ~= nil then
    ControllerGuideManager.IsReady = false
  end
  self.WelcomeText.text = NgoEx.SystemTextFromType("Window_Welcome", Settings.CurrentLanguage.Value)
  AudioManager:StopBgm()
  AudioManager:PlaySeByType("SE_command_execute", false)
  if not startover then
    self.WelcomeIcon.sprite = self.ten
  else
    self.WelcomeIcon.sprite = self.ame
    self.WelcomeIcon.gameObject.transform:DOScale(NEW("Vector3", nil, 0, 2, 1), 0.2):Play()
    self.WelcomeIcon.sprite = self.ten
    self.WelcomeIcon.gameObject.transform:DOScale(NEW("Vector3", nil, 2, 2, 1), 0.2):Play()
  end
  UniTask.Delay(Constants.FAST, false, "Update", nil, false)
end

function C:StartGame(saveNumber)
  if not coroutine.isyieldable() then spawn(C.StartGame, self, saveNumber) return end
  CursorManager:SetCursorShowHide(false)
  self:showWelcome(true)
  Settings.isBackToLoad = false
  Settings.saveNumber = saveNumber
  Resources.UnloadUnusedAssets():ToUniTask(nil, "Update", nil, false)
  SceneManager.LoadScene("WindowUITestScene")
end

function C:CleanEnds()
  for _, endingBlock in EACH(self.endingBlocks) do
    Object.Destroy(endingBlock)
  end
  self.endingBlocks = NEW("List", nil)
end

function C:ShowEnds()
  local mitaEnd = Settings.mitaEnd
  local id = nil
  for _, value in EACH(Enum.GetValues("EndingType")) do
    if value ~= "Ending_None" and value ~= "Ending_Completed" and value ~= "Ending_NetShut" then
      local param = NgoEx.EndingFromType(value)
      id = param.Id
      local endName, endJisseki
      ;(function() local __r; __r, endName, endJisseki = NgoEx.SetEndingTextByLanguage(param); return __r end)()
      if mitaEnd:Exists(function(gotend) return TOSTR(gotend) == id end) then
        local gameObject = Object.Instantiate(self._achievedBlock, self.endingParent)
        gameObject:GetComponent("TooltipCaller").isShowTooltip = true
        gameObject:GetComponent("TooltipCaller").textNakami = CONCAT(CONCAT(endName, "\n"), endJisseki)
        self.endingBlocks:Add(gameObject)
      else
        local gameObject2 = Object.Instantiate(self._unachievedBlock, self.endingParent)
        gameObject2:GetComponent("TooltipCaller").isShowTooltip = true
        gameObject2:GetComponent("TooltipCaller").textNakami = CONCAT(CONCAT(endName, "\n"), endJisseki)
        self.endingBlocks:Add(gameObject2)
      end
    end
  end
end

function C:ChangeLanguage(lang)
  self:CleanEnds()
