end

function C:LoadAssets()
  if not coroutine.isyieldable() then spawn(C.LoadAssets, self) return end
  Debug.Log("LoadAssets")
  NEW("CancellationTokenSource", nil)
  LoadAppData.LoadAppDataAsset()
  self.assetLoadComplete = true
  Debug.Log("assetLoadComplete!!")
end

function C:GetSelectableObjects()
  local list = NEW("List", nil)
  if WindowManager.WindowList.Count > 0 then
    local window = WindowManager.WindowList:FirstOrDefault(function(w) return w.activeState == "Active" end)
    repeat
      local __sw1 = window.appType
      if __sw1 == "ControlPanel" then
        list = window.nakamiApp:GetComponent("ControllPanelView"):GetSelectableObjects()
      elseif __sw1 == "MyPicture" then
        list:AddRange(window.nakamiApp:GetComponentsInChildren("Button"):Select(function(btn) return btn.gameObject end))
      elseif __sw1 == "LastEnd" then
        list:AddRange(window.nakamiApp:GetComponent("adieuDialog").SelectableObjects)
      end
    until true
  elseif self.Caution.interactable then
    list:Add(self.Ok.gameObject)
  elseif self.ChooseUser.interactable then
    list:Add(self.Data1.gameObject)
    list:Add(self.Data2.gameObject)
    list:Add(self.Data3.gameObject)
  elseif self.ChooseDay.interactable and not self.days:GetComponentInChildren("ScrollRect", false) then
    list:Add(self.StartButton.gameObject)
    list:Add(self.days.gameObject)
  end
  return list
end

function C:GetCancelObject()
  if self.ChooseDay.interactable and WindowManager.WindowList.Count <= 0 then
    return self.Back.gameObject
  end
  return nil
end

function C:OnDebugButtonClicked()
  Settings.saveNumber = 4
  SceneManager.LoadScene("Window2DTestScene")
end

return C
